import type { BenefitRule, Brand, Card } from '@/types';

export interface BetaCardGoldenScenario {
    id: string;
    sourceUrl: string;
    card: Card;
    rule: BenefitRule;
    target: Brand;
    amount: number;
    performance: number;
    expectedBenefit: number;
    isOnline?: boolean;
    requiresConfirmation?: boolean;
    monthlyLimit?: number;
    dailyCount?: number;
}

const card = (
    id: string,
    name: string,
    company: string,
    limitTable: Card['limitTable'] = [],
): Card => ({
    id,
    name,
    company,
    color: 'bg-blue-500',
    limitTable,
});

const target = (id: string, categoryId: string): Brand => ({
    id,
    name: id,
    categoryId,
});

const rule = (
    value: Omit<BenefitRule, 'excludedBrands' | 'detail'> & Partial<Pick<
        BenefitRule,
        'excludedBrands' | 'detail'
    >>,
): BenefitRule => ({
    excludedBrands: [],
    detail: '',
    ...value,
});

